//! GDT, TSS, IDT and trap entry.
//!
//! Every vector has a 16-byte entry stub (generated by the assembler) that
//! normalizes the stack to a [`TrapFrame`] and calls [`trap_dispatch`].
//! Double faults, NMIs and machine checks run on their own IST stacks, so a
//! kernel stack overflow (which faults on the guard page) is still reported.

use alloc::boxed::Box;
use core::arch::{asm, global_asm};
use core::sync::atomic::{AtomicU64, Ordering::Relaxed};

use super::regs;
use crate::mm::kspace::{self, STACK_PAGES};
use crate::mm::{PAGE_SIZE, STACKS_BASE};

pub(crate) const KERNEL_CS: u16 = 0x08;
pub(crate) const KERNEL_SS: u16 = 0x10;
const TSS_SEL: u16 = 0x28;

const IST_DOUBLE_FAULT: u8 = 1;
const IST_NMI: u8 = 2;
const IST_MACHINE_CHECK: u8 = 3;

/// First vector used for interrupts (below are CPU exceptions).
pub(crate) const FIRST_IRQ_VECTOR: u8 = 32;

/// Register state saved on every trap. Layout matches the entry stubs.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct TrapFrame {
    pub rax: u64,
    pub rbx: u64,
    pub rcx: u64,
    pub rdx: u64,
    pub rsi: u64,
    pub rdi: u64,
    pub rbp: u64,
    pub r8: u64,
    pub r9: u64,
    pub r10: u64,
    pub r11: u64,
    pub r12: u64,
    pub r13: u64,
    pub r14: u64,
    pub r15: u64,
    pub vector: u64,
    pub error_code: u64,
    pub rip: u64,
    pub cs: u64,
    pub rflags: u64,
    pub rsp: u64,
    pub ss: u64,
}

// Vectors whose exceptions push an error code.
global_asm!(
    ".section .text",
    ".balign 16",
    ".global ichor_trap_stubs",
    "ichor_trap_stubs:",
    ".set vec, 0",
    ".rept 256",
    ".balign 16",
    ".if (vec == 8) || (vec == 10) || (vec == 11) || (vec == 12) || (vec == 13) || (vec == 14) || (vec == 17) || (vec == 21) || (vec == 29) || (vec == 30)",
    ".else",
    "push 0",
    ".endif",
    "push vec",
    "jmp {common}",
    ".set vec, vec + 1",
    ".endr",
    common = sym trap_common,
);

/// Shared tail of every stub: save registers, call the dispatcher, restore.
#[unsafe(naked)]
extern "sysv64" fn trap_common() {
    core::arch::naked_asm!(
        "push r15", "push r14", "push r13", "push r12", "push r11", "push r10", "push r9", "push r8",
        "push rbp", "push rdi", "push rsi", "push rdx", "push rcx", "push rbx", "push rax",
        // 22 quadwords from the 16-byte aligned interrupt frame: aligned.
        "mov rdi, rsp",
        "cld",
        "call {dispatch}",
        // A CPU *exception* (vector < 32) taken in ring 3 does not return to
        // ring 3: it longjmps back into `UserMode::execute`. CS is at frame
        // offset 144, the vector at 120.
        "mov rax, [rsp + 144]",
        "test rax, 3",
        "jz 2f",
        "mov rax, [rsp + 120]",
        "cmp rax, 32",
        "jae 2f",
        "jmp ichor_user_resume",
        "2:",
        "pop rax", "pop rbx", "pop rcx", "pop rdx", "pop rsi", "pop rdi", "pop rbp",
        "pop r8", "pop r9", "pop r10", "pop r11", "pop r12", "pop r13", "pop r14", "pop r15",
        "add rsp, 16",
        "iretq",
        dispatch = sym trap_dispatch,
    )
}

fn stub_address(vector: u8) -> u64 {
    let base: u64;
    // SAFETY: computes an address RIP-relatively; no memory is accessed.
    unsafe {
        asm!("lea {}, [rip + ichor_trap_stubs]", out(reg) base, options(nomem, nostack, preserves_flags))
    };
    base + u64::from(vector) * 16
}

/// The IDT, shared by every CPU. Each gate is two quadwords.
static IDT: [AtomicU64; 512] = [const { AtomicU64::new(0) }; 512];

fn set_gate(vector: u8, ist: u8) {
    let addr = stub_address(vector);
    let low = (addr & 0xffff)
        | (u64::from(KERNEL_CS) << 16)
        | (u64::from(ist) << 32)
        | (0x8e << 40) // present, DPL 0, 64-bit interrupt gate
        | ((addr >> 16) & 0xffff) << 48;
    IDT[vector as usize * 2].store(low, Relaxed);
    IDT[vector as usize * 2 + 1].store(addr >> 32, Relaxed);
}

/// Fills the IDT. Runs once, on the boot CPU.
pub(crate) fn init_idt() {
    for v in 0..=255u8 {
        let ist = match v {
            8 => IST_DOUBLE_FAULT,
            2 => IST_NMI,
            18 => IST_MACHINE_CHECK,
            _ => 0,
        };
        set_gate(v, ist);
    }
}

#[repr(C, packed(4))]
#[derive(Default)]
struct Tss {
    reserved0: u32,
    rsp: [u64; 3],
    reserved1: u64,
    ist: [u64; 7],
    reserved2: u64,
    reserved3: u16,
    iomap_base: u16,
}

crate::cpu_local! {
    /// Address of this CPU's TSS RSP0 field, for `set_rsp0`.
    static RSP0_SLOT: core::sync::atomic::AtomicU64 = core::sync::atomic::AtomicU64::new(0);
}

/// Sets the kernel stack the CPU switches to on a trap from ring 3.
pub(crate) fn set_rsp0(top: u64) {
    let g = crate::cpu::IrqGuard::new();
    let slot = RSP0_SLOT.get(&g).load(Relaxed);
    if slot != 0 {
        // The TSS is `packed(4)`, so `rsp[0]` is only 4-byte aligned; write
        // it as two 32-bit halves. A trap cannot observe a torn value: this
        // CPU is not in ring 3 while it updates its own RSP0.
        let lo = core::ptr::with_exposed_provenance_mut::<u32>(slot as usize);
        let hi = core::ptr::with_exposed_provenance_mut::<u32>(slot as usize + 4);
        // SAFETY: `slot` is the address of this CPU's leaked TSS `rsp[0]`
        // field (set in `init_cpu`), 4-byte aligned; writing it only changes
        // where a ring-3 trap lands.
        unsafe { lo.write_volatile(top as u32) };
        // SAFETY: as above; the high half, 4 bytes up.
        unsafe { hi.write_volatile((top >> 32) as u32) };
    }
}

/// One CPU's GDT and TSS. Leaked: CPUs never go away.
#[repr(C, align(16))]
struct CpuTables {
    gdt: [u64; 7],
    tss: Tss,
}

#[repr(C, packed(2))]
struct DescriptorPointer {
    limit: u16,
    base: u64,
}

/// Builds and loads this CPU's GDT, TSS (with IST stacks) and the shared
/// IDT. Returns `None` if memory for the IST stacks runs out.
pub(crate) fn init_cpu() -> Option<()> {
    let mut tables = Box::new(CpuTables {
        gdt: [
            0,
            0x00af_9a00_0000_ffff, // 0x08 kernel code (64-bit)
            0x00cf_9200_0000_ffff, // 0x10 kernel data
            0x00cf_f200_0000_ffff, // 0x18 user data
            0x00af_fa00_0000_ffff, // 0x20 user code (64-bit)
            0,
            0, // 0x28 TSS (two slots)
        ],
        tss: Tss {
            iomap_base: core::mem::size_of::<Tss>() as u16, // no I/O bitmap
            ..Tss::default()
        },
    });
    for ist in [IST_DOUBLE_FAULT, IST_NMI, IST_MACHINE_CHECK] {
        tables.tss.ist[usize::from(ist - 1)] = kspace::alloc_stack()?;
    }
    let tables: &'static mut CpuTables = Box::leak(tables);
    let tss = core::ptr::addr_of!(tables.tss) as u64;
    let limit = core::mem::size_of::<Tss>() as u64 - 1;
    tables.gdt[5] = (limit & 0xffff)
        | ((tss & 0xff_ffff) << 16)
        | (0x89 << 40) // present, 64-bit available TSS
        | (((tss >> 24) & 0xff) << 56);
    tables.gdt[6] = tss >> 32;
    let rsp0_addr = core::ptr::addr_of!(tables.tss.rsp[0]) as u64;
    {
        let g = crate::cpu::IrqGuard::new();
        RSP0_SLOT.get(&g).store(rsp0_addr, Relaxed);
        crate::cpu::this_block().rsp0_ptr.store(rsp0_addr, Relaxed);
    }
    let tables: &'static CpuTables = tables;

    let gdt = DescriptorPointer {
        limit: (core::mem::size_of::<[u64; 7]>() - 1) as u16,
        base: tables.gdt.as_ptr() as u64,
    };
    let idt = DescriptorPointer {
        limit: (core::mem::size_of_val(&IDT) - 1) as u16,
        base: IDT.as_ptr() as u64,
    };
    // SAFETY: `gdt` describes a 'static GDT whose code/data selectors match
    // `KERNEL_CS`/`KERNEL_SS`; CS is reloaded with a far return to the next
    // instruction and the data segments with the kernel data selector; the
    // TSS descriptor points at a 'static TSS. FS/GS are left alone: in
    // 64-bit mode only their MSR-held bases matter, and reloading GS would
    // clear the per-CPU block pointer.
    unsafe {
        asm!(
            "lgdt [{gdt}]",
            "push {cs}",
            "lea {tmp}, [rip + 2f]",
            "push {tmp}",
            "retfq",
            "2:",
            "mov {tmp:e}, {ss}",
            "mov ss, {tmp:e}",
            "mov ds, {tmp:e}",
            "mov es, {tmp:e}",
            "mov {tmp:e}, {tss}",
            "ltr {tmp:x}",
            "lidt [{idt}]",
            gdt = in(reg) &gdt,
            idt = in(reg) &idt,
            cs = const KERNEL_CS as u64,
            ss = const KERNEL_SS as u32,
            tss = const TSS_SEL as u32,
            tmp = out(reg) _,
        )
    };
    Some(())
}

const EXCEPTION_NAMES: [&str; 32] = [
    "divide error",
    "debug",
    "NMI",
    "breakpoint",
    "overflow",
    "bound range exceeded",
    "invalid opcode",
    "device not available",
    "double fault",
    "coprocessor segment overrun",
    "invalid TSS",
    "segment not present",
    "stack-segment fault",
    "general protection fault",
    "page fault",
    "reserved",
    "x87 floating-point error",
    "alignment check",
    "machine check",
    "SIMD floating-point error",
    "virtualization exception",
    "control protection exception",
    "reserved",
    "reserved",
    "reserved",
    "reserved",
    "reserved",
    "reserved",
    "hypervisor injection exception",
    "VMM communication exception",
    "security exception",
    "reserved",
];

static BREAKPOINTS: AtomicU64 = AtomicU64::new(0);

/// Breakpoint exceptions handled so far.
pub(crate) fn breakpoint_count() -> u64 {
    BREAKPOINTS.load(Relaxed)
}

fn in_stack_guard(addr: u64) -> bool {
    let slot = (STACK_PAGES + 1) * PAGE_SIZE;
    addr >= STACKS_BASE && (addr - STACKS_BASE) % slot < PAGE_SIZE
}

#[allow(clippy::panic)] // Unexpected kernel exceptions are kernel bugs.
extern "sysv64" fn trap_dispatch(f: &mut TrapFrame) {
    let vector = f.vector as u8;
    // An exception taken in ring 3 (not an interrupt, not NMI) is recorded
    // into the thread's context; the stub tail longjmps back into
    // `UserMode::execute`. We must not panic on it: user code faulting is
    // routine.
    if f.cs & 3 == 3 && vector < 32 && vector != 2 {
        super::usermode::record_user_trap(f);
        return;
    }
    match vector {
        3 => {
            BREAKPOINTS.fetch_add(1, Relaxed);
        }
        2 => super::apic::handle_nmi(),
        FIRST_IRQ_VECTOR..=255 => {
            super::apic::handle_irq(vector, f);
            // Preempt only code that ran with interrupts enabled (so it held
            // no guard and no spinlock).
            if f.rflags & (1 << 9) != 0 {
                crate::task::preempt_point();
            }
        }
        14 => {
            let addr = regs::read_cr2();
            let what = if in_stack_guard(addr) {
                " (kernel stack overflow)"
            } else {
                ""
            };
            panic!(
                "page fault at {addr:#x}{what}: error {:#x} at rip {:#x}",
                f.error_code, f.rip
            );
        }
        8 => {
            let what = if in_stack_guard(f.rsp) {
                " (kernel stack overflow)"
            } else {
                ""
            };
            panic!("double fault{what} at rip {:#x}, rsp {:#x}", f.rip, f.rsp);
        }
        _ => panic!(
            "{} (vector {vector}, error {:#x}) at rip {:#x}",
            EXCEPTION_NAMES.get(vector as usize).copied().unwrap_or("?"),
            f.error_code,
            f.rip
        ),
    }
}

/// Executes `int3`; frame's handler counts it and returns.
pub(crate) fn breakpoint() {
    // SAFETY: the IDT is installed and the breakpoint handler returns
    // normally, restoring every register.
    unsafe { asm!("int3", options(nomem, nostack)) };
}
